import type { CheckResult } from './checks';

const DEEPSEEK_API_URL = 'https://api.deepseek.com/v1/chat/completions';

const SYSTEM_PROMPT = `You are a flight tracking system health monitor for airways.gg, a platform that tracks flights at Guernsey Airport (GCI) and surrounding airports.

Your job is to analyze health check results from multiple subsystems (scrapers, flight data, notifications, weather/position data) and identify CORRELATED issues that individual checks would miss.

Look for:
- Multiple services failing simultaneously (possible shared infrastructure outage)
- Cascading failures (one service's downtime causing downstream data gaps)
- Patterns across categories (e.g., scraper gap + weather gap + position gap all starting at the same time)
- Time-based clustering of failures

Return ONLY a valid JSON object with this structure:
{
  "overall_health": "healthy" | "degraded" | "unhealthy",
  "correlated_issues": [
    {
      "severity": "high" | "medium" | "low",
      "title": "brief title",
      "explanation": "clear explanation of the correlation found",
      "confidence": "high" | "medium" | "low",
      "affected_checks": ["check_name_1", "check_name_2"]
    }
  ],
  "false_alarm_suggestions": [
    {
      "check_name": "name of check",
      "reason": "why this might be a false alarm"
    }
  ],
  "summary": "2-3 sentence executive summary"
}

Be conservative. Only flag correlations you are reasonably confident about. Flag uncertain findings as low confidence. Never fabricate issues — if everything looks fine, return healthy with an empty correlated_issues array.`;

export interface LLMCorrelatedIssue {
  severity: 'high' | 'medium' | 'low';
  title: string;
  explanation: string;
  confidence: 'high' | 'medium' | 'low';
  affected_checks: string[];
}

export interface LLMFalseAlarmSuggestion {
  check_name: string;
  reason: string;
}

export interface LLMResponse {
  overall_health: 'healthy' | 'degraded' | 'unhealthy';
  correlated_issues: LLMCorrelatedIssue[];
  false_alarm_suggestions: LLMFalseAlarmSuggestion[];
  summary: string;
  tokens_used?: { input: number; output: number };
}

/**
 * Build the user prompt from check results.
 * Returns { prompt: string, estimatedInputTokens: number }
 */
export function buildPrompt(
  checks: CheckResult[],
  cycleTime: string,
): { prompt: string; estimatedInputTokens: number } {
  let prompt = `HEALTH CHECK — ${cycleTime}\n\n`;

  // Group by category prefix
  const categories = groupByCategory(checks);

  for (const [category, catChecks] of Object.entries(categories)) {
    const catFailed = catChecks.filter(c => !c.passed);
    const catPassed = catChecks.filter(c => c.passed);

    prompt += `=== ${category.toUpperCase()} (${catChecks.length} checks, ${catFailed.length} failing) ===\n`;

    // Show failing checks first with samples
    for (const c of catFailed) {
      prompt += `[FAIL] ${c.name}: ${c.value} (threshold: ${c.threshold})\n`;
      if (c.samples && c.samples.length > 0) {
        prompt += `  Samples: ${JSON.stringify(c.samples.slice(0, 10))}\n`;
      }
    }

    // Show passing checks (compact)
    for (const c of catPassed) {
      prompt += `[PASS] ${c.name}: ${c.value} (threshold: ${c.threshold})\n`;
    }

    prompt += '\n';
  }

  // Rough token estimate: ~4 chars per token
  const estimatedInputTokens = Math.ceil(prompt.length / 4) + Math.ceil(SYSTEM_PROMPT.length / 4);

  return { prompt, estimatedInputTokens };
}

export function groupByCategory(checks: CheckResult[]): Record<string, CheckResult[]> {
  const categories: Record<string, CheckResult[]> = {};

  for (const c of checks) {
    let category: string;
    if (c.name.includes('_last_run') || c.name.includes('_failure_rate') || c.name.includes('_consecutive') || c.name.includes('_zero_records')) {
      category = 'scraper_health';
    } else if (c.name.includes('null_status') || c.name.includes('negative_delay') || c.name.includes('stale_updated') || c.name.includes('orphaned') || c.name.includes('count_vs_avg')) {
      category = 'flight_integrity';
    } else if (c.name.includes('watermark') || c.name.includes('dead_push')) {
      category = 'notification';
    } else if (c.name.includes('weather_gap') || c.name.includes('position_gap') || c.name.includes('stale_weather')) {
      category = 'weather_position';
    } else {
      category = 'other';
    }

    if (!categories[category]) categories[category] = [];
    categories[category].push(c);
  }

  return categories;
}

/**
 * Send check results to DeepSeek V4 Flash for cross-signal analysis.
 * Returns null if the API call fails (caller should fall back to static-only report).
 */
export async function analyzeWithLLM(
  checks: CheckResult[],
  cycleTime: string,
): Promise<LLMResponse | null> {
  const apiKey = process.env.DEEPSEEK_API_KEY;
  if (!apiKey) {
    console.warn('[HealthMonitor] DEEPSEEK_API_KEY not set — skipping LLM tier');
    return null;
  }

  const { prompt: userPrompt, estimatedInputTokens } = buildPrompt(checks, cycleTime);

  const controller = new AbortController();
  const timeoutMs = parseInt(process.env.LLM_TIMEOUT_MS ?? '30000', 10);
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(DEEPSEEK_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: 'deepseek-v4-flash',
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: userPrompt },
        ],
        temperature: 0.1,
        max_tokens: 1024,
      }),
      signal: controller.signal,
    });

    if (!response.ok) {
      const errorText = await response.text().catch(() => 'unknown');
      console.error(`[HealthMonitor] DeepSeek API error ${response.status}: ${errorText.slice(0, 200)}`);
      return null;
    }

    const data = (await response.json()) as {
      choices: [{ message: { content: string } }];
      usage?: { prompt_tokens: number; completion_tokens: number };
    };

    const content = data.choices?.[0]?.message?.content;
    if (!content) {
      console.error('[HealthMonitor] DeepSeek returned empty response');
      return null;
    }

    // Extract JSON from response (may be wrapped in markdown code block)
    let jsonStr = content.trim();
    const jsonMatch = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonMatch) jsonStr = jsonMatch[1].trim();

    const parsed = JSON.parse(jsonStr) as LLMResponse;

    // Attach token usage
    parsed.tokens_used = {
      input: data.usage?.prompt_tokens ?? estimatedInputTokens,
      output: data.usage?.completion_tokens ?? 0,
    };

    return parsed;
  } catch (err) {
    const message = (err as Error).name === 'AbortError'
      ? `LLM request timed out after ${timeoutMs}ms`
      : (err as Error).message;
    console.error('[HealthMonitor] LLM analysis failed:', message);
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

import { describe, it, expect } from 'vitest';
import { buildPrompt, groupByCategory } from './llm';
import type { CheckResult } from './checks';

describe('buildPrompt', () => {
  const sampleChecks: CheckResult[] = [
    { name: 'guernsey_last_run', passed: true, value: '3m ago', threshold: '30m' },
    { name: 'fr24_last_run', passed: true, value: '2m ago', threshold: '30m' },
    {
      name: 'weather_last_run',
      passed: false,
      value: '127m ago',
      threshold: '45m',
      samples: [{ service: 'weather', lastStartedAt: '2026-06-14T12:05:00Z', ageMins: 127 }],
    },
    { name: 'null_status_today', passed: true, value: '0 flights', threshold: 'none' },
    { name: 'negative_delay', passed: true, value: '0 flights', threshold: 'none' },
    { name: 'watermark_lag', passed: true, value: '12 unprocessed', threshold: '≤ 100' },
    {
      name: 'weather_gap_EGJB',
      passed: false,
      value: '115min max gap',
      threshold: '< 120min',
      samples: [{ airportCode: 'EGJB', prevTs: '2026-06-14T10:05:00Z', nextTs: '2026-06-14T12:00:00Z', gapMins: 115 }],
    },
  ];

  it('produces a prompt with correct structure', () => {
    const { prompt } = buildPrompt(sampleChecks, '2026-06-14T14:00:00Z');

    expect(prompt).toContain('HEALTH CHECK — 2026-06-14T14:00:00Z');
    expect(prompt).toContain('SCRAPER_HEALTH');
    expect(prompt).toContain('FLIGHT_INTEGRITY');
    expect(prompt).toContain('NOTIFICATION');
    expect(prompt).toContain('WEATHER_POSITION');
  });

  it('shows failing checks before passing checks in each category', () => {
    const { prompt } = buildPrompt(sampleChecks, '2026-06-14T14:00:00Z');

    const weatherFailIndex = prompt.indexOf('[FAIL] weather_last_run');
    expect(weatherFailIndex).toBeGreaterThan(0);

    const failCount = (prompt.match(/\[FAIL\]/g) || []).length;
    const passCount = (prompt.match(/\[PASS\]/g) || []).length;
    expect(failCount).toBe(2);
    expect(passCount).toBe(5);
  });

  it('includes samples for failing checks', () => {
    const { prompt } = buildPrompt(sampleChecks, '2026-06-14T14:00:00Z');

    expect(prompt).toContain('127m ago');
    expect(prompt).toContain('Samples:');
  });

  it('estimates token count within reasonable bounds', () => {
    const { prompt, estimatedInputTokens } = buildPrompt(sampleChecks, '2026-06-14T14:00:00Z');

    expect(estimatedInputTokens).toBeLessThan(5000);
    expect(estimatedInputTokens).toBeGreaterThan(Math.floor(prompt.length / 4));
  });

  it('handles all-passing checks gracefully', () => {
    const allPassing: CheckResult[] = [
      { name: 'guernsey_last_run', passed: true, value: '3m ago', threshold: '30m' },
      { name: 'null_status_today', passed: true, value: '0 flights', threshold: 'none' },
    ];

    const { prompt } = buildPrompt(allPassing, '2026-06-14T14:00:00Z');
    expect(prompt).not.toContain('[FAIL]');
  });

  it('returns empty string for all-passing with no LLM findings when not heartbeat', () => {
    // buildPrompt always returns a prompt — the silent-when-healthy logic is in buildTelegramMessage
    const { prompt } = buildPrompt(sampleChecks.filter(c => c.passed), '2026-06-14T14:00:00Z');
    expect(prompt).toBeTruthy();
    expect(prompt).not.toContain('[FAIL]');
  });
});

describe('groupByCategory', () => {
  it('classifies scraper health checks', () => {
    const checks: CheckResult[] = [
      { name: 'guernsey_last_run', passed: true, value: '3m', threshold: '30m' },
      { name: 'fr24_failure_rate_6h', passed: true, value: '0', threshold: '≤ 3' },
      { name: 'position_consecutive_failures', passed: true, value: '0', threshold: '< 3' },
      { name: 'adsb_zero_records', passed: true, value: '0', threshold: 'none' },
    ];

    const result = groupByCategory(checks);
    expect(result['scraper_health']).toHaveLength(4);
  });

  it('classifies flight integrity checks', () => {
    const checks: CheckResult[] = [
      { name: 'null_status_today', passed: true, value: '0', threshold: 'none' },
      { name: 'negative_delay', passed: true, value: '0', threshold: 'none' },
      { name: 'stale_updated_at', passed: true, value: '0', threshold: '6h' },
      { name: 'orphaned_flight_times', passed: true, value: '0', threshold: 'none' },
      { name: 'flight_count_vs_avg', passed: true, value: '12', threshold: '50%' },
    ];

    const result = groupByCategory(checks);
    expect(result['flight_integrity']).toHaveLength(5);
  });

  it('classifies notification checks', () => {
    const checks: CheckResult[] = [
      { name: 'watermark_lag', passed: true, value: '12', threshold: '≤ 100' },
      { name: 'dead_push_subs', passed: true, value: '0', threshold: 'none' },
    ];

    const result = groupByCategory(checks);
    expect(result['notification']).toHaveLength(2);
  });

  it('classifies weather and position checks', () => {
    const checks: CheckResult[] = [
      { name: 'weather_gap_EGJB', passed: true, value: '5min', threshold: '< 120min' },
      { name: 'position_gap', passed: true, value: '3min', threshold: '< 60min' },
      { name: 'stale_weather_EGJB', passed: true, value: '2m', threshold: '< 180min' },
    ];

    const result = groupByCategory(checks);
    expect(result['weather_position']).toHaveLength(3);
  });

  it('puts unknown checks in other category', () => {
    const checks: CheckResult[] = [
      { name: 'some_new_check', passed: true, value: 'ok', threshold: 'any' },
    ];

    const result = groupByCategory(checks);
    expect(result['other']).toHaveLength(1);
  });

  it('handles empty array', () => {
    const result = groupByCategory([]);
    expect(Object.keys(result)).toHaveLength(0);
  });
});

describe('CheckResult type', () => {
  it('samples field is optional', () => {
    const result: CheckResult = {
      name: 'test_check',
      passed: true,
      value: 'ok',
      threshold: 'any',
    };
    expect(result.samples).toBeUndefined();
  });

  it('samples can hold multiple rows', () => {
    const result: CheckResult = {
      name: 'test_check',
      passed: false,
      value: '3 issues',
      threshold: 'none',
      samples: [
        { id: 1, reason: 'stale' },
        { id: 2, reason: 'stale' },
        { id: 3, reason: 'stale' },
      ],
    };
    expect(result.samples).toHaveLength(3);
  });
});

import { getDb } from '@airways/database';
import {
  scraperLogs,
  flights,
  notificationWatermark,
  flightStatusHistory,
  pushSubscriptions,
  weatherData,
} from '@airways/database/schema';
import { sql, eq, and, gte, desc } from 'drizzle-orm';

export interface CheckResult {
  name: string;
  passed: boolean;
  value: string;
  threshold: string;
  samples?: Record<string, unknown>[];
}

// ── Service list ───────────────────────────────────────────────────
// Logical service names (our keys) → actual DB scraper_logs.service values.
// Only services that write to scraper_logs are included here.
// Other services (position, weather, notification) are monitored via their
// respective data-table recency checks (position_gap, stale_weather, watermark_lag).
const SCRAPER_SERVICES: { key: string; dbValue: string; staleMins: number }[] = [
  { key: 'guernsey', dbValue: 'guernsey_live', staleMins: parseInt(process.env.STALE_GUERNSEY_MINS ?? '30', 10) },
  { key: 'fr24', dbValue: 'fr24_live', staleMins: parseInt(process.env.STALE_FR24_MINS ?? '30', 10) },
];

function staleThresholdMins(key: string): number {
  const s = SCRAPER_SERVICES.find(s => s.key === key);
  return s?.staleMins ?? 30;
}

function dbServiceName(key: string): string {
  const s = SCRAPER_SERVICES.find(s => s.key === key);
  return s?.dbValue ?? key;
}

// ── Error wrapper — per-check isolation ────────────────────────────

function failedCheck(name: string, threshold: string, reason: string): CheckResult {
  return {
    name,
    passed: false,
    value: 'error',
    threshold,
    samples: [{ error: reason }],
  };
}

async function safeCheck(
  name: string,
  threshold: string,
  fn: () => Promise<CheckResult[]>,
): Promise<CheckResult[]> {
  try {
    return await fn();
  } catch (err) {
    return [failedCheck(name, threshold, (err as Error).message)];
  }
}

// ── Scraper Health Checks (consolidated) ───────────────────────────

/** Last scraper_log per service — staleness check (single query) */
async function checkScraperStaleness(): Promise<CheckResult[]> {
  const db = getDb();
  const now = new Date();
  const results: CheckResult[] = [];

