    console.error(`[HealthMonitor] ${label} check execution failed:`, err);
    await sendAlert('health-monitor', 'critical', `${label} check execution failed`, err).catch(
      () => {},
    );
    return;
  }

  const queryMs = Math.round(performance.now() - t0);
