        .from(scraperLogs)
        .where(sql`${scraperLogs.service} = ${svc.dbValue}`)
        .orderBy(desc(scraperLogs.startedAt))
        .limit(10);

      let consecutive = 0;
      for (const r of rows) {
        if (r.status === 'failure') consecutive++;
        else break;
      }

      const hasData = rows.length > 0;
      return {
        name: `${svc.key}_consecutive_failures` as string,
        passed: consecutive < 3,
